254	        String lastName = owner.getLastName();
255	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
256	        long sequence = ownerRepository.findAll().size() + 1L;
257	        return String.format("%s-%04d", last3, sequence);
