271	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
272	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
273	            .anyMatch(normalized::equals);
274	        if (duplicate) {
275	            throw new DuplicateTelephoneException(normalized);
276	        }
277	    }
